}
const q = (t) => { if (dbType === 'oracle') return '"' + String(t).replace(/"/g, '""') + '"'; if (dbType === 'dm') return String(t); if (dbType === 'mysql' || dbType === 'mariadb' || dbType === 'tidb') return '`' + String(t).replace(/`/g, '``') + '`'; return t; };
const now = new Date().toLocaleString();
